inputs = ['bdud', 'ax', 'cbju', 'xiawcj', 'wjv']
outputs = ['bdud', 'ax', 'cbjcu', 'xiawc', 'wjcv']

# Let's see what we're working with
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"Index {i}: '{inp}' -> '{outp}'")
    if inp != outp:
        # Find the difference position
        min_len = min(len(inp), len(outp))
        diff_pos = -1
        for j in range(min_len):
            if inp[j] != outp[j]:
                diff_pos = j
                break
        if diff_pos == -1:
            # One string is prefix of other
            if len(inp) < len(outp):
                diff_pos = len(inp)
            else:
                diff_pos = len(outp)
        print(f"  Difference at position {diff_pos}")
        if len(inp) < len(outp):
            print(f"  Adding character '{outp[diff_pos]}' at position {diff_pos}")
        elif len(inp) > len(outp):
            print(f"  Removing character '{inp[diff_pos]}' at position {diff_pos}")
        else:
            print(f"  Replacing character '{inp[diff_pos]}' with '{outp[diff_pos]}' at position {diff_pos}")
    print()

